import json, pathlib, statistics, html, sys
root=pathlib.Path(sys.argv[1]);rows=[json.loads(s) for s in (root/'games.jsonl').read_text().splitlines()];manifest=json.loads((root/'manifest.json').read_text());groups={}
def mean(xs):return round(statistics.mean(xs),2) if xs else None
for cohort in sorted({r['cohort'] for r in rows}):
 allrows=[r for r in rows if r['cohort']==cohort];done=[r for r in allrows if r['status']=='complete'];groups[cohort]={'attempted':len(allrows),'complete':len(done),'range':mean([r['range'] for r in done]),'third':mean([r['thirdLag'] for r in done]),'zero':mean([r['zero'] for r in done]),'actions':mean([r['actions'] for r in done]),'medianActions':statistics.median([r['actions'] for r in done]) if done else None,'maxActions':max([r['actions'] for r in done],default=None),'minRange':min([r['range'] for r in done],default=None),'maxRange':max([r['range'] for r in done],default=None),'spent':mean([r['spent'] for r in done]),'breadth':mean([x for r in done for x in r['breadth']]),'hhi':mean([x for r in done for x in r['hhi']]),'auctionPrice':mean([x for r in done for x in r['prices']])}
mixed=[r for r in rows if r['cohort'].startswith('mixed') and r['status']=='complete'];policy={}
for p in ['diversification','concentration']:
 seats=[(r,i) for r in mixed for i in range(4) if r['policies'][i]==p]
 policy[p]={'seats':len(seats),'winCredit':sum(1/len(r['winners']) for r,i in seats if i in r['winners']),'breadth':mean([r['breadth'][i] for r,i in seats]),'hhi':mean([r['hhi'][i] for r,i in seats]),'score':mean([r['scores'][i] for r,i in seats])}
baseline=[json.loads(s) for s in (root/'baseline-v139-games.jsonl').read_text().splitlines()];old=[r for r in baseline if r['players']==4 and r['cohort']=='self' and 8101<=r['seed']<=8106 and r['status']=='complete'];comparison={'v139Greedy':{'n':len(old),'range':mean([r['range'] for r in old]),'third':mean([r['thirdLag'] for r in old]),'actions':mean([r['actions'] for r in old]),'zero':mean([r['zero'] for r in old])},'v140Greedy':groups.get('greedy-control')}
metrics={'groups':groups,'mixedPolicies':policy,'comparison':comparison};(root/'metrics.json').write_text(json.dumps(metrics,indent=2)+'\n')
esc=lambda s:html.escape(str(s));parts=['<!doctype html><meta charset="utf-8"><title>v140 scarcity and diversification</title><style>body{font:17px/1.5 system-ui;max-width:1120px;margin:40px auto;padding:0 24px;color:#24241e;background:#faf8f0}table{border-collapse:collapse;width:100%;font-size:15px}td,th{text-align:left;padding:10px;border-bottom:1px solid #ccc}h1,h2{line-height:1.2}article{background:white;padding:22px;margin:20px 0;border:1px solid #ddd}a{color:#275b74}pre{white-space:pre-wrap;font-size:13px}summary{cursor:pointer}</style><h1>v140 · scarcity and diversification</h1><p>9 November 2026 · Nine deal-flow cards per company · Four-player pilot</p>']
findings=root/'findings.html'
if findings.exists():parts.append(findings.read_text())
parts.append('<h2>Outcomes by table</h2><p>Only completed games enter gap and duration means. Samples are separate from primary games. Breadth is companies held per investor; HHI is concentration (lower means more diversified).</p><table><tr>'+''.join('<th>'+x+'</th>' for x in ['Table','Finished','First–last','First–third','Zero payout','Actions','Cards spent','Breadth','HHI'])+'</tr>')
for name,g in groups.items():parts.append('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in [name,f"{g['complete']}/{g['attempted']}",g['range'],g['third'],g['zero'],g['actions'],g['spent'],g['breadth'],g['hhi']])+'</tr>')
parts.append('</table><h2>Mixed-policy comparison</h2><table><tr><th>Policy</th><th>Seats</th><th>Win credit</th><th>Breadth</th><th>HHI</th><th>Mean score</th></tr>')
for p,g in policy.items():parts.append('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in [p,g['seats'],g['winCredit'],g['breadth'],g['hhi'],g['score']])+'</tr>')
parts.append('</table><p>Complementary lineups use identical setup seeds. Only three independent planner seeds: exploratory evidence, not a reliable ranking. Win credit splits ties. Samples do not enter this table.</p><h2>Rules control</h2><pre>'+esc(json.dumps(comparison,indent=2))+'</pre><p>Six common four-player seeds with the legacy greedy policy. All three rule changes are bundled; the updated greedy forecast also understands catch-up and Sweat Equity without dice. This is not an isolated catch-up effect.</p><h2>Ten reviewed games</h2>')
reviews=json.loads((root/'reviews.json').read_text()) if (root/'reviews.json').exists() else []
for review in reviews:
 seed=review['seed'];parts.append('<article><h3>Game '+str(seed)+'</h3><p>'+esc(review['text'])+'</p><a href="samples/'+str(seed)+'.json">Full events and candidate evaluations</a> · <a href="samples/'+str(seed)+'-replay.json">Replay</a></article>')
parts.append('<h2>Duration and tails</h2><pre>'+esc(json.dumps({k:{x:g[x] for x in ["medianActions","maxActions","minRange","maxRange"]} for k,g in groups.items()},indent=2))+'</pre>')
parts.append('<h2>Reproducibility and limits</h2><p>Hidden hands are sampled, never read. Four samples and four future rounds per decision; candidate and bid lists are bounded. Continuation opponents use a diversification heuristic, and future dice are bland. This does not establish optimal human play.</p><details><summary>Frozen protocol and source identity</summary><pre>'+esc(json.dumps(manifest,indent=2))+'</pre></details><p><a href="manifest.json">Manifest</a> · <a href="games.jsonl">All game records including failures</a> · <a href="metrics.json">Metrics</a> · <a href="source/scripts/scarcity-study.js">Frozen runner</a> · <a href="source/src/dice-planner.js">Frozen planner</a> · <a href="reviews.json">Reviews</a></p>')
(root/'report.html').write_text('\n'.join(parts));print(json.dumps(metrics,indent=2))
